from pathlib import Path
import html
OUT=Path('site'); OUT.mkdir(exist_ok=True)
S={
'inventory':('Housing Inventory & license','https://www.sf.gov/rent-board-housing-inventory'),
'rates':('Current official rates','https://www.sf.gov/reports--current-rates-including-rent-increase-relocation-sec-deposit'),
'guide':('Rent increase guide','https://www.sf.gov/learn-about-rent-increases-san-francisco'),
'ordinance':('Rent Ordinance §37.3','https://www.sf.gov/information--sec-373-rent-limitations'),
'rules':('Rent Board Rules, Part IV','https://www.sf.gov/reports--december-2022--rent-board-rules-and-regulations-part-iv-rent-increases-not-requiring'),
'bank':('Banked increases','https://www.sf.gov/information--banked-rent-increases'),
'notice':('Civil Code §827','https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?sectionNum=827.&lawCode=CIV'),
'state':('Civil Code §1947.12','https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?sectionNum=1947.12.&lawCode=CIV'),
'retaliation':('Civil Code §1942.5','https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?sectionNum=1942.5.&lawCode=CIV'),
'fair':('California CRD housing rights','https://calcivilrights.ca.gov/wp-content/uploads/sites/32/2022/12/Housing-Rights-Booklet_English.pdf'),
'hud':('HUD fair housing enforcement','https://archives.hud.gov/news/2019/pr19-036.cfm'),
'roommates':('Roommates: §6.14 / Costa-Hawkins','https://www.sf.gov/information--rent-increases-under-section-614-and-costa-hawkins'),
'counsel':('SF tenant right-to-counsel notice','https://www.sf.gov/sites/default/files/2023-08/1007%20Notice%20to%20Tenant%20Req%27d%20by%2037.%209(c)-Eng-Sp-Ch-Viet-Rus-Tag[74].pdf')}
def link(k):
 t,u=S[k]; return f'<a href="{html.escape(u,quote=True)}" target="_blank" rel="noopener noreferrer">{t} ↗</a>'
def table(rows,heads=('Question / checkpoint','Finding','Evidence')):
 return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th scope="col">{h}</th>' for h in heads)+'</tr></thead><tbody>'+''.join('<tr><th scope="row">'+a+'</th><td>'+b+'</td><td>'+ ' · '.join(link(k) for k in ks)+'</td></tr>' for a,b,ks in rows)+'</tbody></table></div>'
pages={}
pages['index']=('Executive summary','Start here. License first, then timing, calculation and notice.', '''<section class="hero"><span class="eyebrow">THE FIRST QUESTION</span><h2>Yes. Individual owners need the Rent Board license too.</h2><p>The Housing Inventory requirement is not limited to corporations. Reporting a tenant-occupied unit automatically generates its rent increase license. There is no separate license application described in the official process.</p><p><strong>Legal timing:</strong> a current license must be on file when the annual or banked increase takes effect—not necessarily before you serve the notice. <strong>Recommended sequence:</strong> report and confirm the license first, then serve notice. The license need not be attached, and is not a guarantee against a challenge.</p>'''+link('inventory')+'</section>'+table([
('Ordinary annual benchmark','1.6% for covered units, effective March 1, 2026–February 28, 2027. This is a legal allowance, not a surveyed Outer Sunset market average. A smaller increase or no increase is an option.',['rates','bank']),
('Does the Board approve each increase?','Ordinary annual and correctly calculated banked increases do not require individual Rent Board approval. Housing Inventory reporting and licensing remain required; special increases follow their own rules.',['rules','bank','inventory']),
('Recommended approach — analysis','Consider only the current annual allowance, not an unverified historical catch-up. Use the same neutral review policy for both units, but assess eligibility independently. No proposal here is certified lawful for a specific tenancy.',['guide','retaliation','fair']),
('Do both units need an increase? — analysis','No equal-dollar or simultaneous-increase mandate is established by the cited rules. Different lease terms and lawful anniversary dates can justify different timing. Raising both is not a discrimination safe harbor; protected traits or tenant complaints must not drive the decision.',['guide','fair','retaliation']),
('What is not verified?','Private leases, legal base rents, prior increases, unit coverage, license status and service dates have not been authenticated. Verified case values remain blank. See Unit analysis and Flagged for Review.',['inventory','guide'])])+ '<p class="notice">Research reference, not legal advice or a tenant notice. No filing, tenant service, or attorney review has been performed. No outcome before a tenant lawyer, Rent Board, or court can be guaranteed.</p>')
pages['process']=('License & notice','An evidence-led sequence for an ordinary annual increase.',table([
('01 · Confirm coverage and lease','Establish the applicable rent-control regime, lawful base rent, original move-in, full increase history and current lease restrictions. Do not treat a lease renewal or roommate substitution as automatic vacancy decontrol.',['guide','roommates','notice']),
('02 · Report to the Board','Report required unit information through the Rent Board Portal. Annual deadline: March 1. Reporting is free; late reporting is permitted. Inventory reporting is distinct from the Rent Board fee.',['inventory']),
('03 · Confirm current license','Reporting generates a license for non-owner-occupied units. Confirm it for each unit and retain evidence covering the effective date. Small ownership does not remove this requirement.',['inventory']),
('04 · Check interval and effective-date rate','First annual increase: at least 12 months after lease commencement. Thereafter at least 12 months after the last annual increase. A delayed increase changes the anniversary date. Use the rate on the effective date, not the service date.',['guide']),
('05 · Calculate and explain','Apply the allowable rate to lawful base rent including housing services, excluding temporary passthroughs/fluctuating charges. Do not round up to a whole dollar. Separately identify annual and banked portions; include banked dates if used.',['guide','rules']),
('06 · Prepare written notice','State old base rent, dollar increase, percentage, new rent and effective date; distinguish annual/banked/certified components. Old/new rent are recommended clarity items. Do not describe an ordinary annual increase as a special approved cost reimbursement.',['guide','rules']),
('07 · Serve correctly','Civil Code §827 permits personal delivery or mail for the periodic tenancies it covers. At most 10% cumulative over the preceding 12 months: at least 30 days. More than 10%: at least 90 days. SF guide says add 5 days for mail; §827 incorporates CCP §1013, so check applicable mailing circumstances. Email alone is not the listed procedure.',['notice','guide']),
('08 · Retain review packet — recommendation','Keep lease/history, license evidence, rate source, calculation, notice and dated proof of service. Check repair complaints, accommodation requests and retaliation issues before proceeding. A rate-compliant increase can still face legal objections.',['inventory','retaliation','fair']),
('09 · Recheck before collecting','Confirm valid license and all timing/lease conditions on the effective date. A license is not substantive approval of the amount. Do not backdate or collect skipped months as retroactive annual rent.',['inventory','guide','bank'])]))
pages['rules']=('Rules & owner practices','Local, state and federal layers—not a ZIP-code market-rate target.',table([
('San Francisco annual rate','1.6%: March 1, 2026–February 28, 2027. 1.4%: March 1, 2025–February 28, 2026. 1.7%: March 1, 2024–February 28, 2025. No separate 94122 allowance is established by these citywide sources.',['rates']),
('Formula is not an extra allowance','SF annual allowance is based on 60% of Bay Area CPI change, with a 7% annual ceiling in §37.3(a)(1). The published 1.6% is the applicable ordinary annual rate for the stated window, not 7%.',['ordinance','rates']),
('California cap','Civil Code §1947.12 generally uses the lower of 5% plus cost-of-living change or 10%, subject to exemptions. Subdivision (d)(3) excludes housing subject to a lower valid local cap. Do not add the state allowance to SF’s allowance.',['state']),
('Federal protection','Fair housing law prohibits discrimination in rental terms on protected grounds. The cited HUD enforcement source does not establish a general annual rent percentage for ordinary private SF rentals. Subsidized housing needs separate program review.',['hud','state']),
('Banking is not assumed','Skipped increases generally require 24 full months without an increase to bank; partial unused portions have separate rules. Banked percentages are added, not compounded or prorated; dates and full history matter. No historical total is calculated here.',['bank','rules']),
('Annual reason','Use the actual legal basis: “annual allowable increase under the SF Rent Ordinance,” only when eligible. This route does not require inventing repair costs or demonstrating a specific expense increase.',['ordinance','rules']),
('Special costs / market comparisons','Operating-and-maintenance or capital-improvement increases follow distinct petition/certification rules. Higher expenses or comparable asking rents alone do not authorize an arbitrary increase for a covered tenancy.',['ordinance']),
('Corporations versus individuals','The cited SF annual-rate and licensing rules govern landlords, without a general individual-owner carveout. State exemptions can depend on ownership form and other conditions; those are not blanket exemptions from SF law.',['inventory','state']),
('Actual industry frequency','<span class="flag">UNVERIFIED</span> Official sources reviewed do not establish how often large corporations versus small SF owners actually raise rents. No industry-average percentage or behavior is asserted.',['guide']),
('Practical workflow — recommendation, not survey','Both owner types can use the same checklist: calendar, verified ledger, license confirmation, standardized calculations, compliant service and consistent documented criteria. A manager or software does not replace compliance.',['guide','inventory','notice'])]))
pages['units']=('Unit analysis','Anonymous scenarios. Private facts are not official evidence.', '''<section class="card"><h2>Reported context — unverified, not a verified-value table</h2><p>Study area supplied: Outer Sunset, San Francisco 94122. Reported construction year: 1940; local rent-control coverage is asserted but not independently established.</p><p><strong>Unit A (originally Unit 1):</strong> reported lease start February 1, 2025 at $3,995/month. Reported continuing tenancy April 1, 2026 at $3,995/month, with one original resident remaining and a replacement resident. Residents are referred to only as Resident A, Resident B and replacement Resident C; no supplied initials are published.</p><p><strong>Unit B (originally Unit 2):</strong> reported lease start June 1, 2019 at $3,150/month; residents referred to only as Resident D and Resident E. These dates and amounts are unchanged user reports, not officially verified findings.</p><p>Privacy: no street address, parcel, actual names, initials, leases, account identifiers or private documents are committed. Exact dates and rents can still create re-identification risk; this public site is pseudonymized, not guaranteed anonymous.</p></section>'''+table([
('Unit A · official legal base rent','<span class="blank" aria-label="Unverified value left blank"></span><small>UNVERIFIED · no official unit-specific record reviewed.</small>',['guide']),
('Unit B · official legal base rent','<span class="blank" aria-label="Unverified value left blank"></span><small>UNVERIFIED · no official unit-specific record reviewed.</small>',['guide']),
('Each unit · approved effective date / license status','<span class="blank" aria-label="Unverified value left blank"></span><small>UNVERIFIED · legal eligibility and license not authenticated.</small>',['inventory','guide']),
('Each unit · verified banked entitlement','<span class="blank" aria-label="Unverified value left blank"></span><small>UNVERIFIED · no complete rent/notice history.</small>',['bank']),
('Unit A · continuity analysis','A replacement roommate is not by itself grounds for a market reset or extra-occupant charge. The reported continuing original occupant makes a vacancy-reset theory particularly inappropriate without legal review. The April 1, 2026 paperwork does not by itself prove a new statutory anniversary.',['guide','roommates']),
('Unit B · historical analysis','A 2019 lease does not establish that every intervening increase remains banked. No prior-increase record was supplied. Reconstruct entitlement year by year before attempting banking.',['bank'])])+'''<section class="card"><h2>Conditional arithmetic only — not verified rents</h2><p>Using the reported amounts solely as hypothetical lawful base rents, and only if the 1.6% rate and all eligibility conditions apply:</p><p><strong>Unit A:</strong> $3,995 × 0.016 = $63.92/month; resulting hypothetical rent $4,058.92/month.</p><p><strong>Unit B:</strong> $3,150 × 0.016 = $50.40/month; resulting hypothetical rent $3,200.40/month.</p><p>These are transparent calculations, not official unit-specific amounts, recommendations to serve, or inferred historical entitlements. Verified case outputs above remain blank. If no annual increase ever occurred, the reported original start dates would place the first 12-month threshold at February 1, 2026 and June 1, 2020 respectively; these are conditional arithmetic dates, not approved service/effective dates.</p>'''+link('rates')+' · '+link('guide')+'</section>')
pages['review']=('Tenant-lawyer stress test','Review the substance, timing and motivation—not just the percentage.',table([
('Can a lawyer still challenge it?','Yes. A license does not validate the ledger, coverage, lease rights, notice, service or motive. No attorney has reviewed these units and no “lawyer-proof” result is promised.',['inventory','retaliation','notice']),
('Selective increase — analysis','An increase for only one unit is not automatically discriminatory. Document objective lease/timing/licensing reasons and apply a neutral policy. Do not choose a unit because of a protected characteristic or protected activity.',['fair','retaliation','guide']),
('Both units — analysis','The same percentage when each is eligible can improve consistency, but it is not a legal immunity. Same dates may be inappropriate if a lease or 12-month interval prevents one increase. Different base rents naturally yield different dollars.',['guide','fair']),
('Retaliation red flag','§1942.5 restricts retaliatory increases, including specified tenantability-related activity within its 180-day framework and lawful organizing/exercise of rights. Do not treat day 181 as automatic immunity. Review the full statute and facts.',['retaliation']),
('Fair housing red flag','No higher rent based on protected characteristics, including California source-of-income protections. Do not assume small-owner status eliminates all applicable discrimination protections; exemptions require individualized review.',['fair','hud']),
('Repair/services red flag','Do not disguise reduced services or neglect with an otherwise allowable percentage. Review outstanding repairs and tenant claims independently; the annual allowance is not a release from other legal duties.',['retaliation','guide']),
('Free tenant counsel','SF’s official notice describes free assistance through Tenant Right to Counsel when eviction summons/complaint is received. This is not evidence that every routine rent-increase dispute automatically receives a free personal lawyer.',['counsel']),
('Suggested explanation — not a legal notice','“This is an annual allowable rent adjustment under the SF Rent Ordinance, not an additional-occupant charge. The notice identifies the percentage, dollar change and effective date.” Use only if accurate and accompanied by compliant notice/service.',['guide','rules'])]))
pages['flagged']=('Flagged for Review','Published limitations. These do not block publishing the research.',table([
('F01 · Unit records','<span class="flag">UNVERIFIED</span> No official authentication of legal base rents, lease history, construction year, exemptions, license status or prior notices. Verified-value fields remain empty; reported context is explicitly separated. Source links explain requirements, not proof of private facts.',['inventory','guide']),
('F02 · Missing history','<span class="flag">NEEDS REVIEW</span> No banking total, definitive anniversary or ready-to-serve notice is issued. Unit A continuity and Unit B historical entitlement require records.',['bank','roommates']),
('F03 · Official example date error','<span class="flag">SOURCE IRREGULARITY</span> The main guide’s first worked example labels June 1, 2025 as carrying 1.6%, while its 2026 scenario and current rates support June 1, 2026. Use the effective-period rate schedule, not that mislabeled sentence.',['guide','rates']),
('F04 · Banking example date error','<span class="flag">SOURCE IRREGULARITY</span> The banking page describes a 2025 increase but one sentence calls its 1.4% annual allowance “August 1, 2024.” The rates page assigns 1.4% to March 2025–February 2026. No reliance on that mislabeled year.',['bank','rates']),
('F05 · Search excerpt stale','<span class="flag">RESOLVED FOR RATE</span> A search excerpt of the general guide showed 1.4%. Direct page retrieval showed 1.6%, corroborated by the current rate schedule. This site uses 1.6% only for the verified window.',['guide','rates']),
('F06 · No verified market norm','<span class="flag">UNVERIFIED</span> No official Outer Sunset “normal” discretionary percentage or corporation/individual frequency dataset established. The legal annual allowance is not a market survey.',['rates']),
('F07 · Other regimes and future dates','<span class="flag">NEEDS REVIEW</span> Subsidy status, lease restrictions and any operative emergency rules need transaction-date review. No 2027–2028 rate or unit-specific exemption is inferred.',['state','guide']),
('F08 · Public privacy limits','<span class="flag">CAUTION</span> Public website contains no supplied identifiers, but retained dates/rents may enable matching. Housing Inventory submissions themselves are public; do not submit false placeholders to government filings. This project has made no such filing.',['inventory']),
('F09 · Professional review','<span class="flag">NOT PERFORMED</span> No SF lawyer approval, tenant service, portal login or government filing. Public official-source research cannot substitute for case-specific legal review.',['notice','inventory'])]))
pages['sources']=('Sources & verification','Official sources only. Checked November 7, 2026 UTC.', '<p>Method: read official SF guidance, rate schedule, ordinance and notice rules; compare California statutory text and official civil-rights materials. Search snippets are discovery aids, not substitutes where direct page content was available. Each table row links its authority. “Analysis” labels identify recommendations rather than official findings. A linked legal rule does not authenticate private tenancy facts.</p>'+table([(t,'Official authority · checked 2026-11-07. '+('Retrieved and read directly.' if k in ['inventory','rates','guide','ordinance','rules','notice','state','retaliation'] else 'Official-source extracted text reviewed through research retrieval; not a full PDF/page legal audit.'),[k]) for k,(t,u) in S.items()])+ '<p>Scope: repository review found only a short README and no prior factual content to audit. External availability can change; restricted sandbox networking prevents an independent HTTP crawl of government hosts. Internal links and every row’s official-source link are checked automatically; external source retrieval was performed with the research tools. No claim is made that every linked government page is free of errors.</p>')
nav=[('index','Overview'),('process','License & notice'),('rules','Rules & practices'),('units','Unit analysis'),('review','Tenant-lawyer review'),('flagged','Flagged for Review'),('sources','Sources')]
for slug,(title,desc,body) in pages.items():
 n=''.join(f'<a href="{s}.html"'+(' aria-current="page"' if s==slug else '')+f'>{label}</a>' for s,label in nav)
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{html.escape(desc,quote=True)}"><title>{title} · SF Rental Review</title><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#main">Skip to content</a><aside><a class="brand" href="index.html"><span class="mark">SF</span> Rental Review</a><p class="aside-label">OWNER RESEARCH DESK</p><nav aria-label="Main">{n}</nav><div class="aside-foot">Independent research<br>Not a government website<br><strong>Privacy-first edition</strong></div></aside><div class="workspace"><header><span>San Francisco / Residential rent</span><span class="checked">Checked 07 Nov 2026</span></header><main id="main"><div class="page-title"><span class="eyebrow">RENT-CONTROLLED HOUSING</span><h1>{title}</h1><p>{desc}</p></div>{body}</main><footer>SF Rental Review · Official-source research, not legal advice. <a href="flagged.html">Read limitations</a> · <a href="sources.html">Source register</a></footer></div></body></html>'''
 (OUT/f'{slug}.html').write_text(doc)
print(f'Built {len(pages)} pages')
